// ── Turing Machine Simulator ────────────────────────────────────
// Recognises {aⁿbⁿcⁿ | n ≥ 0} — not context-free!
// Strategy: repeatedly find and mark one 'a', one 'b', one 'c'.
// Uses X/Y/Z as markers on the tape.

function simulateTM(input) {
  const tape = ['B', ...input.split(''), 'B']; // B = blank
  let head = 1; // start after leading blank
  let state = 'q0';
  const steps = [];
  let limit = 10000;

  // Simplified TM for a^n b^n c^n — just validate with counting
  // (A full TM simulation would manage tape writes; here we show the logic)
  const counts = { a: 0, b: 0, c: 0 };
  let phase = 'a';
  for (const ch of input) {
    if (phase === 'a') {
      if (ch === 'a') { counts.a++; }
      else if (ch === 'b') { phase = 'b'; counts.b++; }
      else return 'REJECT';
    } else if (phase === 'b') {
      if (ch === 'b') { counts.b++; }
      else if (ch === 'c') { phase = 'c'; counts.c++; }
      else return 'REJECT';
    } else {
      if (ch === 'c') { counts.c++; }
      else return 'REJECT';
    }
  }
  if (input === '') return 'ACCEPT'; // ε ∈ language
  return (counts.a === counts.b && counts.b === counts.c) ? 'ACCEPT' : 'REJECT';
}

console.log(simulateTM('aabbcc')); // ACCEPT
console.log(simulateTM('abc'));    // ACCEPT
console.log(simulateTM(''));       // ACCEPT
console.log(simulateTM('aabbc')); // REJECT
console.log(simulateTM('aabcc')); // REJECT

// ── Halting problem: why no general solver can exist ─────────────
// Pseudo-code proof (not runnable — deliberately):
//
// function halts(programCode, input) {
//   // Assume this decider exists.
// }
//
// function diagonal(programCode) {
//   if (halts(programCode, programCode)) {
//     while (true) {} // loop if halts says HALT
//   } else {
//     return;          // stop if halts says LOOP
//   }
// }
//
// diagonal(diagonal) => contradiction in both cases.
// Therefore `halts` cannot exist for all inputs.
console.log('Halting problem is undecidable — no program can solve it for all inputs.');

// ── Rice's theorem (consequence) ────────────────────────────────
// Any non-trivial semantic property of programs is undecidable.
// You cannot write a program that decides, for all programs P:
//   - Does P terminate on all inputs?
//   - Does P ever output 42?
//   - Does P contain a bug?
// All undecidable by Rice's theorem.

// ── Church-Turing Thesis ─────────────────────────────────────────
// "Every effectively computable function is Turing-computable."
// Equivalent models (all compute the same functions):
//   - Turing machines
//   - Lambda calculus (Church)
//   - Recursive functions (Gödel-Herbrand-Kleene)
//   - Random-access machines (RAM model of real CPUs)
//   - JavaScript (any Turing-complete language)
//   - Conway's Game of Life (yes, really)

// ── Decidable vs. Recognisable ───────────────────────────────────
// Decidable (recursive): TM always halts with ACCEPT or REJECT.
//   Examples: regular languages, CFLs, many number-theory problems.
//
// RE (Turing-recognisable): TM halts+accepts if string IS in L,
//   may loop forever if string is NOT in L.
//   Example: halting problem — we can simulate M on w; if it halts, accept;
//            if not, we loop — we never know when to reject.
//
// Neither RE nor co-RE: complement of halting problem;
//   no TM ever accepts all non-halting (M, w) pairs.

// ── Reductions: showing a problem is undecidable ─────────────────
// To show problem B is undecidable, reduce halting problem to B:
//   If B were decidable, we could use it to decide halting — contradiction.
// Common undecidable problems (all proved via reduction from halting):
//   - Does program P always terminate? (totality)
//   - Does P's output ever equal 42? (output prediction)
//   - Are two programs equivalent? (program equivalence)
//   - Does P have a security vulnerability? (general static analysis)
console.log('Undecidability is pervasive — it is why perfect static analysis is impossible.');
